import { create } from 'zustand';
import { persist } from 'zustand/middleware';

// ─── Canonical types shared across the app ───────────────────────────────────

export interface FunctionParameter {
  name: string;
  type: string;
}

export interface FunctionSignature {
  name: string;
  parameters: FunctionParameter[];
  returnType: string;
}

/** An example explicitly provided in the original problem statement. */
export interface OfficialExample {
  input: string;
  output: string;
  explanation?: string;
}

/** A test case generated by the AI – treated as a candidate, not ground truth. */
export interface GeneratedTest {
  input: string;
  expectedOutput: string;
  type: 'normal' | 'edge' | 'boundary' | 'stress';
  explanation?: string;
}

export interface StarterCode {
  java: string;
  python: string;
  c: string;
  [key: string]: string;
}

export interface ProblemData {
  title: string;
  description: string;
  constraints: string[];
  inputFormat?: string;
  outputFormat?: string;
  /** Official examples extracted verbatim from the problem statement. */
  examples: OfficialExample[];
  functionSignature: FunctionSignature;
  starterCode: StarterCode;
  /** AI-generated test cases – structurally valid but not guaranteed correct. */
  generatedTests: GeneratedTest[];
}

// ─── Zustand store ────────────────────────────────────────────────────────────

interface ProblemStore {
  currentProblem: ProblemData | null;
  setCurrentProblem: (problem: ProblemData) => void;
  clearCurrentProblem: () => void;
}

export const useProblemStore = create<ProblemStore>()(
  persist(
    (set) => ({
      currentProblem: null,
      setCurrentProblem: (problem) => set({ currentProblem: problem }),
      clearCurrentProblem: () => set({ currentProblem: null }),
    }),
    {
      name: 'codelaunch-problem-storage',
    }
  )
);
